def solve(data):
    packages = data['packages']
    roots = data['roots']
    blocked = data.get('blocked', {})
    pins = data.get('pins', {})
    features = set(data.get('features', []))
    names = sorted(packages)

    if any(name not in packages for name in roots):
        return {'error': 'unsatisfiable'}

    root_limits = {
        name: [(interval[0], interval[1])]
        for name, interval in roots.items()
    }
    best = None
    best_vector = None

    def active_deps(row):
        return [
            dep for dep in row.get('deps', [])
            if not dep.get('feature') or dep['feature'] in features
        ]

    def is_acyclic(selected):
        graph = {}
        for name, row in selected.items():
            deps = active_deps(row)
            if any(dep['name'] not in packages for dep in deps):
                return False
            graph[name] = [dep['name'] for dep in deps]

        state = {}

        def visit(name):
            if state.get(name) == 1:
                return False
            if state.get(name) == 2:
                return True
            state[name] = 1
            for dep_name in graph[name]:
                if dep_name not in graph or not visit(dep_name):
                    return False
            state[name] = 2
            return True

        return all(visit(name) for name in graph)

    def search(assigned, selected, required, limits):
        nonlocal best, best_vector
        unresolved = sorted(required - set(assigned))
        if not unresolved:
            if not is_acyclic(selected):
                return
            vector = tuple(assigned.get(name, -1) for name in names)
            if best_vector is None or vector > best_vector:
                best = dict(assigned)
                best_vector = vector
            return

        name = unresolved[0]
        for row in choose(packages[name]):
            version = row['version']
            if any(not (low <= version <= high) for low, high in limits.get(name, [])):
                continue
            if version in blocked.get(name, []):
                continue
            if name in pins and version != pins[name]:
                continue

            deps = active_deps(row)
            if any(dep['name'] not in packages for dep in deps):
                continue

            next_assigned = dict(assigned)
            next_assigned[name] = version
            next_selected = dict(selected)
            next_selected[name] = row
            next_required = required | {dep['name'] for dep in deps}
            next_limits = {key: list(ranges) for key, ranges in limits.items()}
            feasible = True
            for dep in deps:
                dep_name = dep['name']
                low, high = dep['min'], dep['max']
                next_limits.setdefault(dep_name, []).append((low, high))
                if dep_name in next_assigned and not (low <= next_assigned[dep_name] <= high):
                    feasible = False
                    break
            if feasible:
                search(next_assigned, next_selected, next_required, next_limits)

    search({}, {}, set(roots), root_limits)
    if best is None:
        return {'error': 'unsatisfiable'}
    return {'versions': best}
